import { ViewTransition } from 'react'

// Remounts on every navigation, so the outgoing page runs `exit` and the
// incoming page runs `enter`. The `nav-forward` / `nav-back` transition types
// are set by the Links via `transitionTypes`; untyped navigations (e.g. the
// browser back button) fall back to a cross-fade.
export default function Template({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ViewTransition
      enter={{
        'nav-forward': 'page-slide-in-from-right',
        'nav-back': 'page-slide-in-from-left',
        default: 'page-fade-in',
      }}
      exit={{
        'nav-forward': 'page-slide-out-to-left',
        'nav-back': 'page-slide-out-to-right',
        default: 'page-fade-out',
      }}
    >
      {children}
    </ViewTransition>
  )
}

