@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ───────────────────────── View transitions ─────────────────────────
   Class names below are assigned by <ViewTransition> enter/exit/update/share
   props (app/template.tsx, page components). All animation is gated behind
   prefers-reduced-motion: no-preference. */

@media (prefers-reduced-motion: no-preference) {
  /* Directional page slides: forward pushes left, back pushes right. */
  ::view-transition-old(.page-slide-out-to-left) {
    animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-out-to-left;
  }

  ::view-transition-new(.page-slide-in-from-right) {
    animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in-from-right;
  }

  ::view-transition-old(.page-slide-out-to-right) {
    animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-out-to-right;
  }

  ::view-transition-new(.page-slide-in-from-left) {
    animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in-from-left;
  }

  /* Untyped navigations (browser back/forward, etc.) cross-fade. */
  ::view-transition-old(.page-fade-out) {
    animation: 200ms ease-out both vt-fade-out;
  }

  ::view-transition-new(.page-fade-in) {
    animation: 200ms ease-in both vt-fade-in;
  }

  /* Suspense reveal: skeleton cross-fades into streamed-in content. */
  ::view-transition-old(.suspense-reveal) {
    animation: 250ms ease-out both vt-fade-out;
  }

  ::view-transition-new(.suspense-reveal) {
    animation: 250ms ease-in both vt-fade-in;
  }

  /* Shared product image: the browser morphs position/size; just tune timing. */
  ::view-transition-group(.product-image-morph) {
    animation-duration: 300ms;
    animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  }
}

@keyframes vt-slide-out-to-left {
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

@keyframes vt-slide-in-from-right {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
}

@keyframes vt-slide-out-to-right {
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}

@keyframes vt-slide-in-from-left {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
}

@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
}

/* Respect reduced motion: no view-transition animation (updates apply
   instantly, including the default shared-element morph) and no skeleton
   pulsing. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

